    const injectWikipediaStyles = () => {
      const wikipediaStyles = ["https://en.wikipedia.org/w/load.php?modules=site.styles", "https://en.wikipedia.org/w/load.php?modules=ext.cite.styles", "https://en.wikipedia.org/w/load.php?modules=ext.scribunto.styles", "https://en.wikipedia.org/w/load.php?modules=skins.vector.styles"];
      wikipediaStyles.forEach(url => {
        if (!document.querySelector(`link[href="${url}"]`)) {
          const styleTag = document.createElement("link");
          styleTag.rel = "stylesheet";
          styleTag.href = url;
          document.head.appendChild(styleTag);
        }
      });
    };
    const handleHoverInfobox = _ref => {
      let {
        fieldKey,
        infoboxTitle
      } = _ref;
      if (props.pageTitle !== infoboxTitle) return;
      const infobox = divRef.value.querySelector(".infobox, .sidebar, .toccolours");
      if (!infobox) return;
      clearInfoboxHighlights();
      const rows = infobox.querySelectorAll("tr");
      for (const row of rows) {
        const th = row.querySelector("th");
        if (th && th.textContent.trim() === fieldKey) {
          row.classList.add("infobox-highlight");
          break;
        }
      }
    };
    const handleUnhoverInfobox = () => {
      clearInfoboxHighlights();
      clearTextHighlights();
    };
    const handleSelection = content => {
      const isTable = /<table.*?>.*?<\/table>/s.test(content);
      const selection = window.getSelection();
      if (!selection || selection.rangeCount === 0) return;
      const range = selection.getRangeAt(0);
      const selectedNodes = range.cloneContents().childNodes;
      let sourceId = undefined;
      for (const node of selectedNodes) {
        if (node.nodeType === Node.ELEMENT_NODE && /^h[1-6]$/i.test(node.tagName)) {
          sourceId = node.id;
          break;
        }
      }
      if (!sourceId) {
        let startElement = range.startContainer;
        while (startElement && !/^h[1-6]$/i.test(startElement.tagName)) {
          startElement = startElement.parentElement;
        }
        sourceId = startElement ? startElement.id : undefined;
      }
      if (!sourceId) {
        selectedText.value[props.divId] = content;
        bus.emit(`${props.divId}_Event`, {
          content
        });
        showPopup.value[props.divId] = true;
        nextTick(() => {
          updatePopupPosition();
        });
        return;
