          linkedItem: null,
          chapterContent: ""
        };
      }
      const linkedItem = props.linkedOutline.find(linked => linked.leftId === sourceId || linked.rightId === sourceId);
      if (!linkedItem) {
        return {
          linkedItem: null,
          chapterContent: ""
        };
      }
      const targetContainerId = sourceContainerId === "div1" ? "div3" : "div1";
      const targetId = sourceContainerId === "div1" ? linkedItem.rightId : linkedItem.leftId;
      const targetContainer = document.getElementById(targetContainerId);
