        return {
          linkedItem: null,
          chapterContent: ""
        };
      }
      const targetElement = targetContainer.querySelector(`#${targetId}`);
      if (!targetElement) {
        return {
          linkedItem: null,
          chapterContent: ""
        };
      }
      let chapterContent = "";
      let currentNode = targetElement;
      while (currentNode) {
        if (currentNode !== targetElement && currentNode.nodeType === Node.ELEMENT_NODE && /^h[1-6]$/i.test(currentNode.tagName)) {
          break;
        }
        if (currentNode.nodeType === Node.ELEMENT_NODE || currentNode.nodeType === Node.TEXT_NODE) {
