    };

    //---------------------------------------------------------------
    // 🔥 修改后的核心部分：跨 span / 节点句子高亮逻辑
    //---------------------------------------------------------------
    // 标点集合
    const SENTENCE_TERMINATORS = /[.!?。！？；;:\n]/;

    // 获取元素内所有文本节点（排除 infobox）
    const getTextNodesInElement = element => {
      const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, {
        acceptNode: function (node) {
          if (!node.textContent || !node.textContent.trim()) return NodeFilter.FILTER_REJECT;
          let parent = node.parentNode;
          while (parent && parent !== element) {
            if (parent.classList && (parent.classList.contains("infobox") || parent.classList.contains("sidebar") || parent.classList.contains("toccolours"))) {
              return NodeFilter.FILTER_REJECT;
            }
            parent = parent.parentNode;
          }
          return NodeFilter.FILTER_ACCEPT;
        }
      }, false);
      const nodes = [];
      let n;
      while (n = walker.nextNode()) {
        nodes.push(n);
      }
      return nodes;
    };
    const buildMergedTextAndMap = textNodes => {
      let merged = "";
      const map = [];
      for (const node of textNodes) {
        const start = merged.length;
        const txt = node.textContent;
        merged += txt;
        const end = merged.length;
        map.push({
          node,
          start,
          end
        });
      }
      return {
        merged,
        map
      };
    };
    const findNodeForIndex = (map, idx) => {
      for (const entry of map) {
        if (idx >= entry.start && idx < entry.end) {
          return {
            node: entry.node,
            offset: idx - entry.start
          };
        }
      }
      const last = map[map.length - 1];
      return {
        node: last.node,
        offset: last.end - last.start
      };
    };
    const findSentenceBoundsInMerged = (merged, matchStart, matchEnd) => {
      let start = 0;
      for (let i = matchStart - 1; i >= 0; i--) {
        if (SENTENCE_TERMINATORS.test(merged[i])) {
          start = i + 1;
          break;
        }
      }
      while (start < merged.length && /\s/.test(merged[start])) start++;
      let end = merged.length;
      for (let i = matchEnd; i < merged.length; i++) {
        if (SENTENCE_TERMINATORS.test(merged[i])) {
          end = i + 1;
          break;
        }
      }
      while (end < merged.length && /[)\]"'’”]/.test(merged[end])) end++;
      return {
        start,
        end
      };
    };
    const wrapMergedRangeWithSpan = (map, startIdx, endIdx, highlightClass) => {
      const startInfo = findNodeForIndex(map, startIdx);
      const endInfo = findNodeForIndex(map, endIdx - 1);
      const range = document.createRange();
      range.setStart(startInfo.node, startInfo.offset);
      range.setEnd(endInfo.node, endInfo.offset + 1);
      let ancestor = range.commonAncestorContainer;
      if (ancestor.nodeType === Node.TEXT_NODE) ancestor = ancestor.parentNode;
      if (ancestor && ancestor.closest && ancestor.closest(".sentence-highlight")) return null;
      const wrapper = document.createElement("span");
      wrapper.className = `sentence-highlight ${highlightClass}`;
      try {
        range.surroundContents(wrapper);
        return wrapper;
      } catch {
        const extracted = range.extractContents();
        wrapper.appendChild(extracted);
        range.insertNode(wrapper);
        return wrapper;
      }
    };
    const highlightSentencesInElement = (element, searchText, highlightClass) => {
      if (!element || !searchText) return;
      const textNodes = getTextNodesInElement(element);
      if (!textNodes.length) return;
      let {
        merged,
        map
      } = buildMergedTextAndMap(textNodes);
      let startIndex = 0;
      while (true) {
        const found = merged.indexOf(searchText, startIndex);
        if (found === -1) break;
        const matchStart = found;
        const matchEnd = found + searchText.length;
        const {
          start,
          end
        } = findSentenceBoundsInMerged(merged, matchStart, matchEnd);
        wrapMergedRangeWithSpan(map, start, end, highlightClass);
        startIndex = end;
